<script lang="ts">
 import {languageOverrides} from "./localization";
 import {version} from "../package.json";
 import {translator} from "./i18n";import {Download,RefreshCw} from '@lucide/svelte';import {updateState,automaticUpdateCheck,setAutomaticUpdateCheck,checkForUpdates,installUpdate} from './update-service';import {native} from './storage';export let language:'ru'|'ro'|"en";export let prepare:()=>Promise<boolean>;let automatic=automaticUpdateCheck();$:ru=language==='ru';
 $:t=translator(language,$languageOverrides);
</script>
<article class="panel update-settings"><h2>{t('Обновления','Actualizări')}</h2><p>OpenHaU {version}</p><label class="check-row"><input type="checkbox" bind:checked={automatic} onchange={()=>setAutomaticUpdateCheck(automatic)}/>{t('Проверять обновления при запуске','Verifică actualizările la pornire')}</label><p>{t('Обновления загружаются с GitHub. Перед установкой программа проверяет подпись пакета и предлагает сохранить работу.','Actualizările se descarcă de pe GitHub. Înainte de instalare aplicația verifică semnătura pachetului și propune salvarea lucrului.')}</p><div class="actions"><button class="button secondary" disabled={!native||$updateState.checking||$updateState.installing} onclick={()=>checkForUpdates(true)}><RefreshCw size={17}/>{t('Проверить обновления','Verifică actualizări')}</button>{#if $updateState.version}<button class="button" disabled={$updateState.installing} onclick={()=>installUpdate(prepare)}><Download size={17}/>{t('Установить','Instalează')} {$updateState.version}</button>{/if}</div>{#if $updateState.error}<p role="alert" class="alert error">{$updateState.error}</p>{:else if $updateState.checking}<p>{t('Проверка…','Se verifică…')}</p>{:else if $updateState.checked&&!$updateState.version}<p>{t('Установлена актуальная версия.','Este instalată versiunea actuală.')}</p>{/if}{#if $updateState.installing}<progress max={$updateState.total||undefined} value={$updateState.total?$updateState.downloaded:undefined}></progress>{/if}{#if $updateState.notes}<pre>{$updateState.notes}</pre>{/if}<a href="https://github.com/OldschoolNetwork/open-hau/releases" target="_blank" rel="noreferrer">GitHub Releases</a></article>
<style>.update-settings{display:grid;gap:18px}.update-settings h2,.update-settings p{margin:0}.actions{display:flex;gap:10px;flex-wrap:wrap}pre{white-space:pre-wrap;font:inherit}progress{width:100%}</style>
